previewCss:
.darma-loader-darma-b16-barometer-needle { --accent: var(--loader-color, #0f766e); --accent-2: var(--loader-secondary-color, #f59e0b); width: var(--loader-size, 114px); height: var(--loader-size, 114px); position: relative; }
.darma-loader-darma-b16-barometer-needle .darma-loader-darma-b16-barometer-needle__face { position: absolute; inset: 0; border-radius: 50%; background: radial-gradient(circle at 42% 36%, color-mix(in srgb, #fff 45%, transparent), transparent 70%), color-mix(in srgb, var(--accent) 14%, transparent); box-shadow: inset 0 0 0 4px color-mix(in srgb, var(--accent) 55%, transparent); }
.darma-loader-darma-b16-barometer-needle .darma-loader-darma-b16-barometer-needle__ticks { position: absolute; inset: 9%; border-radius: 50%; background: repeating-conic-gradient(from 0deg, color-mix(in srgb, var(--accent) 60%, transparent) 0 1.5deg, transparent 1.5deg 30deg); mask: radial-gradient(circle, transparent 0 76%, #000 77%); -webkit-mask: radial-gradient(circle, transparent 0 76%, #000 77%); }
.darma-loader-darma-b16-barometer-needle .darma-loader-darma-b16-barometer-needle__needle { position: absolute; left: 48%; top: 14%; width: 4%; height: 38%; border-radius: 3px 3px 0 0; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 20%, var(--accent-2))); transform-origin: 50% 100%; animation: darma-loader-darma-b16-barometer-needle-baro-swing calc(var(--loader-speed, 1s) * 3.6) cubic-bezier(.45, 0, .3, 1) infinite; }
.darma-loader-darma-b16-barometer-needle .darma-loader-darma-b16-barometer-needle__hub { position: absolute; left: 43%; top: 43%; width: 14%; height: 14%; border-radius: 50%; background: linear-gradient(#94a3b8, #334155); }
@keyframes darma-loader-darma-b16-barometer-needle-baro-swing { 0%, 100% { transform: rotate(-118deg); } 22% { transform: rotate(-42deg); } 44% { transform: rotate(-76deg); } 66% { transform: rotate(64deg); } 84% { transform: rotate(18deg); } }

